"""Lender DEMO models — SAMPLE DATA ONLY, generated by seed_demo.

No real scoring, no real fraud models, no real personal data.
Every lender page shows a "DEMO — sample data" banner.
"""
from django.db import models


class LenderSme(models.Model):
    """A sample SME in the lender's portfolio view."""

    ref_id = models.CharField(max_length=20, unique=True)
    name = models.CharField(max_length=120)
    sector = models.CharField(max_length=60)
    location = models.CharField(max_length=60)
    health_score = models.IntegerField(default=0)  # 0-100
    risk_band = models.CharField(max_length=1, default="C")  # A-E
    monthly_revenue_trend = models.JSONField(
        default=list, help_text="Last 6-12 months of monthly revenue (sample)"
    )
    compliance_history = models.JSONField(
        default=list, help_text="e.g. [{month:'2026-05', score: 88}]"
    )
    credit_score = models.IntegerField(default=0)
    credit_reasons = models.JSONField(default=list, help_text="Top-5 explainable reasons")
    consent_status = models.CharField(max_length=12, default="granted")  # granted|expired|revoked|none

    def __str__(self):
        return f"{self.name} (band {self.risk_band})"


class FraudAlert(models.Model):
    """Sample fraud alert for the demo feed. NOT a real detection model."""

    sme = models.ForeignKey(
        "lender.LenderSme", null=True, blank=True, on_delete=models.SET_NULL, related_name="alerts"
    )
    kind = models.CharField(max_length=60)  # e.g. sim_swap_before_loan_request
    severity = models.CharField(
        max_length=10, choices=[("info", "Info"), ("warning", "Warning"), ("critical", "Critical")]
    )
    explanation = models.TextField()
    suggested_action = models.TextField(blank=True)
    detected_at = models.DateTimeField()

    class Meta:
        ordering = ["-detected_at"]

    def __str__(self):
        return f"[{self.severity}] {self.kind}"


class LoanApplication(models.Model):
    """Sample loan application with a suggested decision + reasons."""

    sme = models.ForeignKey(
        "lender.LenderSme", on_delete=models.CASCADE, related_name="applications"
    )
    amount = models.DecimalField(max_digits=14, decimal_places=2)
    currency = models.CharField(max_length=3, default="USD")
    purpose = models.CharField(max_length=200)
    suggested = models.CharField(
        max_length=12, choices=[("recommend", "Recommend"), ("review", "Review"), ("decline", "Decline")]
    )
    reasons = models.JSONField(default=list)
    submitted_at = models.DateTimeField()

    class Meta:
        ordering = ["-submitted_at"]

    def __str__(self):
        return f"{self.sme.name}: {self.amount} ({self.suggested})"
